    <script>
        const mockData = {
            '12345': {
                name: 'John Doe',
                dob: '1985-05-15',
                policy: 'Active'
            }
        };

        function lookupMember() {
            const policyNumber = document.getElementById('policy-number').value;
            const memberId = document.getElementById('member-id').value;
            let detailsDiv = document.getElementById('member-details');

            if (mockData[memberId]) {
                const member = mockData[memberId];
                detailsDiv.innerHTML = `<p>Name: ${member.name}</p><p>DOB: ${member.dob}</p><p>Policy Status: ${member.policy}</p>`;
            } else {
                detailsDiv.innerText = 'Member not found. Please check the details and try again.';
            }
        }

        document.getElementById('claim-form').addEventListener('submit', function(e) {
            e.preventDefault();
            this.style.display = 'none';
            const refNumber = `MS-2026-08-${Math.floor(1000 + Math.random() * 9000)}`;
            document.getElementById('reference-number').innerText = refNumber;
            document.getElementById('confirmation').style.display = 'block';
        });

        document.getElementById('documents').addEventListener('change', function() {
            const fileList = document.getElementById('file-list');
            fileList.innerHTML = '';
            for (const file of this.files) {
                const listItem = document.createElement('li');
                listItem.innerText = file.name;
                fileList.appendChild(listItem);
            }
        });
    </script>
